<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Abyx 3D Interactive Experience</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: #0a0a12;
            color: #ffffff;
            overflow: hidden;
        }

        #canvas-container {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            z-index: 1;
        }

        #ui-layer {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            padding: 30px;
            z-index: 2;
            pointer-events: none;
        }

        .hud-top {
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: linear-gradient(90deg, rgba(15, 30, 60, 0.8) 0%, rgba(20, 40, 80, 0.6) 50%, rgba(5, 15, 30, 0.8) 100%);
            backdrop-filter: blur(10px);
            padding: 20px 40px;
            border-radius: 20px;
            border: 1px solid rgba(100, 200, 255, 0.3);
            max-width: 60%;
        }

        .hud-left {
            display: flex;
            gap: 40px;
        }

        .hud-item {
            text-align: left;
        }

        .hud-label {
            font-size: 12px;
            color: #6ebaff;
            letter-spacing: 3px;
            text-transform: uppercase;
            margin-bottom: 5px;
        }

        .hud-value {
            font-size: 24px;
            font-weight: 700;
            background: linear-gradient(180deg, #fff 0%, rgba(150, 200, 255, 0.7) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .hud-right {
            display: flex;
            align-items: center;
            gap: 30px;
        }

        #title-block {
            pointer-events: auto;
        }

        #title-block h1 {
            font-size: 42px;
            font-weight: 700;
            background: linear-gradient(180deg, #6ebaff 0%, #fff 50%, #6ebaff 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            letter-spacing: 6px;
            margin-bottom: 10px;
            text-shadow: 0 0 30px rgba(110, 186, 255, 0.5);
        }

        #title-block p {
            font-size: 14px;
            color: rgba(200, 230, 255, 0.7);
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        .hud-controls {
            display: flex;
            gap: 15px;
        }

        .control-btn {
            background: rgba(30, 60, 90, 0.6);
            border: 1px solid rgba(110, 186, 255, 0.4);
            color: #fff;
            padding: 15px 25px;
            font-size: 13px;
            cursor: pointer;
            transition: all 0.3s ease;
            border-radius: 8px;
            text-transform: uppercase;
            letter-spacing: 2px;
            backdrop-filter: blur(5px);
        }

        .control-btn:hover {
            background: rgba(110, 186, 255, 0.3);
            box-shadow: 0 0 20px rgba(110, 186, 255, 0.4);
            transform: translateY(-3px);
        }

        .hud-bottom {
            position: absolute;
            bottom: 30px;
            left: 50%;
            transform: translateX(-50%);
            text-align: center;
            pointer-events: none;
        }

        .pulse-ring {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(110, 186, 255, 0.5) 0%, transparent 70%);
            margin: 0 auto 15px;
            animation: pulse 2s ease infinite;
        }

        .hud-bottom-text {
            font-size: 14px;
            color: rgba(200, 230, 255, 0.6);
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        @keyframes pulse {
            0%, 100% { transform: scale(1); opacity: 0.7; }
            50% { transform: scale(1.2); opacity: 1; }
        }

        #loading-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(5, 10, 20, 0.9);
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 1000;
            transition: opacity 0.8s ease;
        }

        #loading-overlay.hidden {
            opacity: 0;
            pointer-events: none;
        }

        .loader-text {
            font-size: 32px;
            letter-spacing: 10px;
            background: linear-gradient(90deg, transparent, rgba(110, 186, 255, 0.7), transparent);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .loader-bar {
            width: 300px;
            height: 4px;
            background: rgba(110, 186, 255, 0.3);
            border-radius: 2px;
            margin-top: 20px;
            overflow: hidden;
        }

        .loader-fill {
            height: 100%;
            width: 0%;
            background: linear-gradient(90deg, #6ebaff, #fff, #6ebaff);
            animation: loadProgress 2s ease forwards;
        }

        @keyframes loadProgress {
            0% { width: 0%; }
            50% { width: 40%; }
            100% { width: 100%; }
        }

        #instruction-overlay {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(10, 20, 40, 0.8);
            backdrop-filter: blur(20px);
            padding: 60px 100px;
            border-radius: 30px;
            text-align: center;
            border: 1px solid rgba(110, 186, 255, 0.4);
            z-index: 999;
            pointer-events: none;
            transition: opacity 0.8s ease, transform 0.8s ease;
        }

        #instruction-overlay.hidden {
            opacity: 0;
            transform: translate(-50%, -60%);
        }

        .instructions {
            font-size: 24px;
            letter-spacing: 3px;
            color: rgba(200, 230, 255, 0.8);
        }

        .instructions i {
            display: inline-block;
            margin: 0 10px 10px;
            background: rgba(110, 186, 255, 0.2);
            padding: 15px 20px;
            border-radius: 12px;
            font-size: 18px;
        }

        #stats-panel {
            position: fixed;
            bottom: 30px;
            right: 30px;
            background: rgba(15, 30, 60, 0.7);
            backdrop-filter: blur(15px);
            padding: 25px;
            border-radius: 20px;
            border: 1px solid rgba(110, 186, 255, 0.3);
            pointer-events: auto;
        }

        #stats-panel h4 {
            font-size: 14px;
            color: #6ebaff;
            margin-bottom: 10px;
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        .stat-item {
            display: flex;
            justify-content: space-between;
            margin-top: 8px;
            font-size: 13px;
        }

        #fps-counter, #frame-count {
            color: rgba(255, 200, 150, 0.9);
        }

        .fps-bar {
            width: 200px;
            height: 6px;
            background: rgba(100, 150, 180, 0.3);
            border-radius: 3px;
            overflow: hidden;
            margin-top: 5px;
        }

        .fps-fill {
            height: 100%;
            width: 60%;
            background: linear-gradient(90deg, #f5d96e, #fff, #f5d96e);
            border-radius: 3px;
            animation: fpsFill 2s ease infinite alternate;
        }

        @keyframes fpsFill {
            0% { width: 50%; }
            100% { width: 75%; }
        }
    </style>
</head>
<body>
    <!-- Loading Screen -->
    <div id="loading-overlay">
        <span class="loader-text">INITIALIZING ABYX CORE</span>
        <div class="loader-bar"><div class="loader-fill"></div></div>
    </div>

    <!-- Instructions Overlay -->
    <div id="instruction-overlay">
        <p class="instructions">
            <i>&larr;</i> 
            <i>&rarr;</i> Move Camera 
            <br><span style="font-size: 20px; display: block;">&uarr;</span> &nbsp;<span style="font-size: 20px;">&darr;</span> Zoom
            <br><br>
            <b style="color: rgba(110, 186, 255, 0.9);">CLICK ANYWHERE</b> TO BEGIN INTERACTION
        </p>
    </div>

    <!-- Stats Panel -->
    <div id="stats-panel" style="display:none;">
        <h4>SYSTEM STATUS</h4>
        <div class="stat-item">
            <span>FPS</span><span id="fps-counter">0</span>
        </div>
        <div class="fps-bar"><div class="fps-fill"></div></div>
        <div class="stat-item">
            <span id="frame-count">0</span> FRAMES RENDERED
        </div>
    </div>

    <!-- HUD Top -->
    <div id="ui-layer" style="display:none;">
        <div class="hud-top">
            <div class="hud-left">
                <div class="hud-item">
                    <div class="hud-label">System</div>
                    <div class="hud-value" id="sys-status">ONLINE</div>
                </div>
                <div class="hud-item">
                    <div class="hud-label">Dimension</div>
                    <div class="hud-value">THREE-DIMENSIONAL</div>
                </div>
            </div>
            <div class="hud-right" id="title-block">
                <h1>ABYX INTERACTIVE</h1>
                <p>VORTEX ENGINE // VERSION 2.0 // PRODUCTION GRADE</p>
            </div>
        </div>

        <div class="hud-bottom">
            <div class="pulse-ring"></div>
            <p class="hud-bottom-text">Interactive WebGL Experience • Move to Explore • Click to Interact</p>
        </div>

        <!-- Stats Panel -->
        <div id="stats-panel">
            <h4>SYS STATUS</h4>
            <div class="stat-item">
                <span>FPS</span><span id="fps-counter">0</span>
            </div>
            <div class="fps-bar"><div class="fps-fill"></div></div>
            <div class="stat-item">
                <span id="frame-count">0</span> FRAMES RENDERED
            </div>
        </div>
    </div>

    <!-- 3D Canvas Container -->
    <div id="canvas-container"></div>

    <!-- Three.js CDN (Production-Ready) -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/build/three.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/examples/js/controls/OrbitControls.js"></script>

    <script>
        // ====================================================
        // ABYX 3D INTERACTIVE SYSTEM - PRODUCTION GRADE CORE
        // ====================================================

        const System = {
            camera: null,
            renderer: null,
            controls: null,
            scene: null,
            clock: new THREE.Clock(),

            meshes: [],
            particles: null,
            lighting: {
                ambientLight: null,
                directionalLight: null,
                pointLights: []
            },

            state: {
                loaded: false,
                fps: 0,
                frameCount: 0,
                mouse: new THREE.Vector2(),
                interactionActive: false
            }
        };

        const Constants = {
            FOG_COLOR: 0x0a0a15,
            BACKGROUND: 0x050510,
            HIGHLIGHT: 0x6ebaff,
            DARKNESS: 0x2e7dff,
            ACCENT_RED: 0xff3366,
            PARTICLE_COUNT: 8000,
            SCENE_SIZE: 40
        };

        // ====================================================
        // INITIALIZATION & LOADING
        // ====================================================

        function init() {
            const container = document.getElementById('canvas-container');

            // Scene Setup
            System.scene = new THREE.Scene();
            System.scene.background = new THREE.Color(Constants.BACKGROUND);
            System.scene.fog = new THREE.FogExp2(Constants.FOG_COLOR, 0.15);

            // Camera Configuration (Orbit-style)
            System.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            System.camera.position.set(0, 4, 12);

            // WebGL Renderer with High Settings
            System.renderer = new THREE.WebGLRenderer({
                antialias: true,
                alpha: false,
                powerPreference: 'high-performance'
            });

            System.renderer.setSize(window.innerWidth, window.innerHeight);
            System.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
            container.appendChild(System.renderer.domElement);

            // Orbit Controls (Interactive Camera)
            System.controls = new THREE.OrbitControls(
                System.camera, 
                System.renderer.domElement
            );
            System.controls.enableDamping = true;
            System.controls.dampingFactor = 0.05;
            System.controls.autoRotate = false;
            System.controls.autoRotateSpeed = 0.5;

            // Lighting Setup (Production-Grade)
            setupLighting();

            // Build Scene Elements
            buildScene();

            // Event Bindings
            bindEvents();

            // Initial Render
            System.renderer.render(System.scene, System.camera);

            // Start Animation Loop
            requestAnimationFrame(animate);

            System.state.loaded = true;

            // Hide Loading & Instructions after delay
            setTimeout(() => {
                document.getElementById('loading-overlay').classList.add('hidden');
                document.getElementById('instruction-overlay').classList.add('hidden');
                document.querySelector('#ui-layer[style*="display:none"]').style.display = 'block';
                document.getElementById('stats-panel').style.display = 'block';
            }, 2500);
        }

        // ====================================================
        // LIGHTING SYSTEM
        // ====================================================

        function setupLighting() {
            // Ambient Light (Soft Base)
            System.lighting.ambientLight = new THREE.AmbientLight(0x404060, 0.5);
            System.scene.add(System.lighting.ambientLight);

            // Directional Light (Sun-like Primary Source)
            System.lighting.directionalLight = new THREE.DirectionalLight(
                Constants.HIGHLIGHT, 
                1.2
            );
            System.lighting.directionalLight.position.set(10, 20, 15);
            System.scene.add(System.lighting.directionalLight);

            // Point Lights (Atmospheric Effects)
            for (let i = 0; i < 3; i++) {
                const pl = new THREE.PointLight(
                    i % 2 === 0 ? Constants.HIGHLIGHT : Constants.ACCENT_RED,
                    0.6,
                    50
                );

                const positions = [
                    [-15, -5, -10], [8, -3, -12], [-8, 3, -15]
                ];
                pl.position.copy(positions[i]);
                System.scene.add(pl);
                System.lighting.pointLights.push(pl);
            }
        }

        // ====================================================
        // SCENE OBJECT CONSTRUCTION
        // ====================================================

        function buildScene() {
            // --- 1. Central Core Structure (Complex Polyhedron) ---
            const coreGeo = new THREE.IcosahedronGeometry(2, 3);
            const coreMaterial = new THREE.MeshStandardMaterial({
                color: Constants.HIGHLIGHT,
                roughness: 0.15,
                metalness: 0.8,
                wireframe: false,
                envMapIntensity: 0.6
            });

            const core = new THREE.Mesh(coreGeo, coreMaterial);
            System.scene.add(core);
            System.meshes.push({ mesh: core, type: 'core' });

            // --- 2. Wireframe Outer Shell (Energy Field) ---
            const shellGeo = new THREE.IcosahedronGeometry(4.5, 1);
            const shellMaterial = new THREE.MeshBasicMaterial({
                color: Constants.DARKNESS,
                wireframe: true,
                transparent: true,
                opacity: 0.3
            });

            const shell = new THREE.Mesh(shellGeo, shellMaterial);
            System.scene.add(shell);
            System.meshes.push({ mesh: shell, type: 'shell' });

            // --- 3. Particle Field (8000+ Particles) ---
            createParticleField();

            // --- 4. Floating Geometric Orbits (Decoration) ---
            const orbitGroups = [];

            // Orbit Group 1 - Triangle Ring
            createOrbitRing(orbitGroups, 6, [2, 0], Constants.HIGHLIGHT, 'Triangle', true);

            // Orbit Group 2 - Square Ring
            createOrbitRing(orbitGroups, 4, [3, -1.5], 0x7a9bff, 'Square', true);

            // Orbit Group 3 - Hexagon Ring (Rotating)
            createOrbitRing(orbitGroups, 6, [4, 2.5], 0x88b5ff, 'Hexagon', true);

            // --- 5. Interactive Ray-Sphere (Click Target) ---
            const raySphereGeo = new THREE.SphereGeometry(1.5, 32, 16);
            const raySphereMat = new THREE.MeshStandardMaterial({
                color: Constants.HIGHLIGHT,
                roughness: 0.2,
                metalness: 0.7,
                emissive: 0x224455,
                emissiveIntensity: 0.3
            });

            const raySphere = new THREE.Mesh(raySphereGeo, raySphereMat);
            System.scene.add(raySphere);
            System.meshes.push({ mesh: raySphere, type: 'ray-sphere' });
        }

        // ====================================================
        // ORBIT SYSTEM CREATION (Multi-Orbit)
        // ====================================================

        function createOrbitRing(parentGroup, count, position, color, name, isTriangle = false) {
            const orbitGeo = new THREE.RingGeometry(0.15, 0.25, 64);
            const orbitMat = new THREE.MeshStandardMaterial({
                color: color,
                side: THREE.DoubleSide,
                roughness: 0.3,
                metalness: 0.6
            });

            const orbitMesh = new THREE.Mesh(orbitGeo, orbitMat);
            System.scene.add(orbitMesh);

            // Add particle trail
            for (let i = 0; i < count; i++) {
                const particleGeo = new THREE.BufferGeometry();
                const positions = new Float32Array([
                    Math.random() * 8 - 4, 
                    Math.random() * 6 - 3, 
                    Math.random() * 5 - 2.5
                ]);

                const particleMat = new THREE.PointsMaterial({
                    color: isTriangle ? 0x6ebaff : (isTriangle && i === 1) ? Constants.ACCENT_RED : color,
                    size: isTriangle ? 0.8 : 0.5,
                    transparent: true,
                    opacity: 0.7
                });

                const particles = new THREE.Points(
                    particleGeo, 
                    particleMat
                );

                particles.position.copy(position);
                if (isTriangle) {
                    particles.rotation.y = i / count * Math.PI * 2;
                } else {
                    particles.position.x = (i - count/2) / count * 6.5;
                }

                System.scene.add(particles);
            }
        }

        // ====================================================
        // PARTICLE SYSTEM (High-Count Dynamic Field)
        // ====================================================

        function createParticleField() {
            const particleGeo = new THREE.BufferGeometry();

            // Initialize Particle Positions
            const positions = [];
            const velocities = [];
            const sizes = [];
            const colors = [];

            for (let i = 0; i < Constants.PARTICLE_COUNT; i++) {
                // Random spherical distribution
                const theta = Math.random() * Math.PI * 2;
                const phi = Math.acos(1 - 2 * Math.random());

                const radius = 8 + Math.cbrt(Math.random()) * 40;

                positions.push(
                    radius * Math.sin(phi) * Math.cos(theta),
                    radius * Math.sin(phi) * Math.sin(theta),
                    radius * Math.cos(phi)
                );

                velocities.push(
                    (Math.random() - 0.5) * 0.02,
                    (Math.random() - 0.5) * 0.02,
                    (Math.random() - 0.5) * 0.02
                );

                sizes.push(Math.random() * 1.2);

                // Multi-color particle system
                const color = new THREE.Color();
                if (Math.random() > 0.6) {
                    color.setHSL(
                        Math.random(), 
                        0.7 + Math.random() * 0.3, 
                        0.4 + Math.random() * 0.2
                    );
                } else {
                    color.setHex(Constants.HIGHLIGHT);
                    if (i % 5 === 0) {
                        color.setHex(0x991188); // Purple accent
                    }
                }

                colors.push(color.r, color.g, color.b);
            }

            particleGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
            particleGeo.setAttribute('color', new THREE.BufferAttribute(new Float32Array(colors), 3));
            particleGeo.setAttribute('size', new THREE.BufferAttribute(new Float32Array(sizes), 1));

            System.particles = {
                mesh: new THREE.Points(particleGeo, 
                    new THREE.PointsMaterial({
                        vertexColors: true,
                        size: 0.8,
                        transparent: false
                    })
                ),
                velocities: velocities
            };

            // Scale particle system to scene
            System.particles.mesh.scale.set(1.5, 1.5, 1.5);
            System.scene.add(System.particles.mesh);
        }

        // ====================================================
        // INTERACTIVE EVENT HANDLING
        // ====================================================

        function bindEvents() {
            // Window Resize (Responsive)
            window.addEventListener('resize', () => {
                const container = document.getElementById('canvas-container');
                System.camera.aspect = container.clientWidth / container.clientHeight;
                System.renderer.setSize(container.clientWidth, container.clientHeight);
            });

            // Mouse Move (Interactive Cursor)
            window.addEventListener('mousemove', (e) => {
                // Track mouse for subtle camera interaction
                if (!System.state.loaded) return;

                const normalizedX = (e.clientX / window.innerWidth) * 2 - 1;
                const normalizedY = -(e.clientY / window.innerHeight) * 2 + 1;

                System.camera.position.x += normalizedX * 0.01;
                System.camera.position.y += normalizedY * 0.01;
            });

            // Click Event (Activate Interaction Mode)
            document.addEventListener('click', () => {
                if (!System.state.loaded) return;

                // Visual feedback on click
                createClickEffect();

                // Pulse all meshes briefly
                System.meshes.forEach(m => {
                    m.mesh.scale.multiplyScalar(1.05);
                    setTimeout(() => {
                        m.mesh.scale.divideScalar(1.05);
                    }, 50);
                });

                // Rotate shell on click
                const shell = document.querySelector('.shell');
                if (shell) {
                    shell.rotation.y += Math.PI / 8;
                }
            });

            // Keyboard Controls
            window.addEventListener('keydown', (e) => {
                if (!System.state.loaded) return;

                switch(e.code) {
                    case 'ArrowUp':
                        System.camera.position.z -= 0.3;
                        break;
                    case 'ArrowDown':
                        System.camera.position.z += 0.3;
                        break;
                    case 'ArrowLeft':
                        System.camera.position.x -= 0.3;
                        break;
                    case 'ArrowRight':
                        System.camera.position.x += 0.3;
                        break;
                }
            });

            // Mouse Click for Instruction Overlay
            const instructionOverlay = document.getElementById('instruction-overlay');
            if (instructionOverlay) {
                instructionOverlay.addEventListener('click', () => {
                    instructionOverlay.classList.add('hidden');
                });
            }
        }

        // ====================================================
        // VISUAL CLICK EFFECT
        // ====================================================

        function createClickEffect() {
            const clickGroup = new THREE.Group();

            for (let i = 0; i < 24; i++) {
                const particleGeo = new THREE.BufferGeometry();
                const positions = new Float32Array([0, 0, 0]);

                const particleMat = new THREE.PointsMaterial({
                    color: Constants.HIGHLIGHT,
                    size: 1.5,
                    transparent: true,
                    opacity: 1
                });

                const particles = new THREE.Points(particleGeo, particleMat);

                clickGroup.add(particles);
            }

            System.scene.add(clickGroup);

            // Animate and remove after 300ms
            let time = 0;
            const animateClick = () => {
                time += 16;
                if (time < 300) {
                    clickGroup.position.copy(System.camera.position.clone().add(
                        new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5) * 2
                    ));

                    System.meshes.forEach(m => {
                        if (m.type === 'shell') {
                            m.mesh.rotation.z += 0.01;
                        }
                    });

                    requestAnimationFrame(animateClick);
                } else {
                    System.scene.remove(clickGroup);
                }
            };

            animateClick();
        }

        // ====================================================
        // RENDER LOOP (Animation & Performance Tracking)
        // ====================================================

        function animate(time) {
            if (!System.state.loaded) return;

            const delta = System.clock.getDelta();
            System.state.frameCount++;

            // Calculate FPS
            if (time % 16 < 5) {
                System.state.fps = Math.round(1000 * delta);
                updateStats(System.state.fps, System.state.frameCount);
            }

            // Animate Meshes
            const currentTime = time * 0.001;

            // Core rotation animation
            if (System.meshes[0]) {
                const core = System.meshes[0].mesh;
                core.rotation.x += 0.003 + delta * 0.5;
                core.rotation.y += 0.005 + delta * 0.3;

                // Pulse effect on core
                core.scale.setScalar(1 + Math.sin(currentTime * 2) * 0.01);
            }

            // Shell rotation (slower, opposite direction)
            if (System.meshes[1]) {
                const shell = System.meshes[1].mesh;
                shell.rotation.y -= 0.004 - delta * 0.2;
                shell.rotation.x += Math.sin(currentTime * 1.5) * 0.002;
            }

            // Particle field gentle rotation
            if (System.particles) {
